-- AI match reasons for professors and programs
-- Generated by comparing entity data against user_profile.research_background

ALTER TABLE professors ADD COLUMN match_reason TEXT;
ALTER TABLE programs ADD COLUMN match_reason TEXT;

-- Single-row applicant profile used as input to match reasoning
CREATE TABLE IF NOT EXISTS user_profile (
  id TEXT PRIMARY KEY DEFAULT 'me',
  research_background TEXT,
  target_fields TEXT,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
INSERT OR IGNORE INTO user_profile (id) VALUES ('me');
